export type Recipient = {
  id: string
  name: string
  maskedAccount: string
  currency: string
}

export const RECENT_RECIPIENTS: Recipient[] = [
  { id: "r1", name: "Amara Okafor", maskedAccount: "•••• 4821", currency: "NGN" },
  { id: "r2", name: "Liam Chen", maskedAccount: "•••• 0093", currency: "SGD" },
  { id: "r3", name: "Priya Nair", maskedAccount: "•••• 7710", currency: "INR" },
  { id: "r4", name: "Sofia Marchetti", maskedAccount: "•••• 2246", currency: "EUR" },
]

const FX_RATES: Record<string, number> = {
  NGN: 1580.32,
  SGD: 1.34,
  INR: 83.12,
  EUR: 0.93,
}

const FEE_PERCENT = 0.007
const FEE_FIXED = 1.99

export function getRate(currency: string): number {
  return FX_RATES[currency] ?? 1
}

export function calculateFee(sendAmount: number): number {
  if (!Number.isFinite(sendAmount) || sendAmount <= 0) return 0
  return Math.round((sendAmount * FEE_PERCENT + FEE_FIXED) * 100) / 100
}

export function convert(sendAmount: number, currency: string): number {
  const fee = calculateFee(sendAmount)
  const net = Math.max(sendAmount - fee, 0)
  return Math.round(net * getRate(currency) * 100) / 100
}

export type SendMoneyData = {
  recipientId: string | null
  recipientName: string
  recipientMasked: string
  recipientCurrency: string
  sendAmount: string
  receiveAmount: string
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipientId: null,
  recipientName: "",
  recipientMasked: "",
  recipientCurrency: "",
  sendAmount: "",
  receiveAmount: "",
}

export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const

export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (p: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (i: number) => void
}

