"use client"

import { useMemo, useState } from "react"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { RECENT_RECIPIENTS } from "../schema"
import type { SendMoneyStepProps } from "../schema"
import { RecipientRow } from "./_parts"

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return RECENT_RECIPIENTS
    return RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(q))
  }, [query])

  const select = (id: string) => {
    const recipient = RECENT_RECIPIENTS.find((r) => r.id === id)
    if (!recipient) return
    patch({
      recipientId: recipient.id,
      recipientName: recipient.name,
      recipientMasked: recipient.maskedAccount,
      recipientCurrency: recipient.currency,
    })
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="recipient-search" size="sm">
          Search recipients
        </Label>
        <Input
          id="recipient-search"
          type="search"
          placeholder="Name or account"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          size="md"
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <span
          style={{
            fontSize: "var(--atlas-text-caption)",
            fontWeight: "var(--atlas-font-weight-medium)",
            color: "var(--atlas-foreground-muted)",
          }}
        >
          Recent recipients
        </span>
        {filtered.map((r) => (
          <RecipientRow key={r.id} recipient={r} selected={data.recipientId === r.id} onSelect={() => select(r.id)} />
        ))}
        {filtered.length === 0 && (
