"use client"

import type { ReactNode } from "react"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import type { Recipient } from "../schema"

export function RecipientRow({
  recipient,
  selected,
  onSelect,
}: {
  recipient: Recipient
  selected: boolean
  onSelect: () => void
}) {
  return (
    <Card
      variant={selected ? "elevated" : "outlined"}
      interactive
      selected={selected}
      onClick={onSelect}
    >
      <CardContent
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: "var(--atlas-spacing-3)",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-0_5)" }}>
          <span
            style={{
              fontSize: "var(--atlas-text-body)",
              fontWeight: "var(--atlas-font-weight-medium)",
              color: "var(--atlas-foreground)",
            }}
          >
            {recipient.name}
          </span>
          <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>
            {recipient.maskedAccount}
          </span>
        </div>
        <Badge variant="secondary" size="sm">
          {recipient.currency}
        </Badge>
      </CardContent>
    </Card>
  )
}

export function SummaryRow({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "var(--atlas-spacing-2)" }}>
      <span style={{ color: "var(--atlas-foreground-muted)", fontSize: "var(--atlas-text-body-sm)" }}>{label}</span>
      <span
        style={{
          color: "var(--atlas-foreground)",
          fontSize: "var(--atlas-text-body-sm)",
          fontWeight: "var(--atlas-font-weight-medium)",
        }}
      >
        {value}
      </span>
    </div>
  )
}
